From Ltac2 Require Import Ltac2 Constr Std Control.
Ltac2 cert_refl_vm (rhs : constr) :=
  let g := Control.goal () in
  let r := constr:(@eq_refl _ $rhs) in
  Std.exact_no_check (Constr.Unsafe.make (Constr.Unsafe.Cast r Constr.Cast.vm g)).
Set Default Proof Mode "Ltac2".
Lemma LM_cert16 : (match wstartx TM IMGW (vars_below (s_next (LM_P0 16))) 10 (LM_P0 16) P0RUN (xconst (NODES 16) GD16) with
                   | Some l => forallb (fun X => fin_q (LM_TAIL_Q 16) [0x973c8] (s_next (LM_P0 16)) (xs_st X)) l | None => false end) = true.
Proof. cert_refl_vm constr:(true). Qed.
Lemma LM_cert0 : (match wstartx TM IMGW (vars_below (s_next (LM_P0 0))) 10 (LM_P0 0) P0RUN (xconst (NODES 0) GD0) with
                  | Some l => forallb (fun X => fin_q (LM_TAIL_Q 0) [0x973c8] (s_next (LM_P0 0)) (xs_st X)) l | None => false end) = true.
Proof. cert_refl_vm constr:(true). Qed.
Set Default Proof Mode "Classic".
End LmA.


