Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Open Scope Z_scope.
Definition CS_SF5 (c : Z) : csite := mk_csite SF5_P0 SF5_Q KEEPK []
  ([(VSub 0 0, 2304 - c, RW); (VCopy 12, 0, RW); (VCopy 10, 0, RZ); (VCopy 14, 0, RW); (VCopy 6, 0, RO)] ++ RTV).
Definition P2RUN : plan := PRun 600 [0x4b14c; 0x63d24; 0x976b0] [].
Definition XNJe (pc : Z) : Z * xaction := (pc, xjoin JR (fun _ => PRun 400 [0x976b0] [])).
Definition NODES2 (c : Z) : list (Z * xaction) := [(0x4b14c, XCallK (CS_SF5 c)); XNJe 0x97660; (0x976b0, XHand (hx_promote 0x976b0 10))].
From Ltac2 Require Import Ltac2 Constr Std Control.
Ltac2 cert_refl_vm (rhs : constr) :=
  let g := Control.goal () in
  let r := constr:(@eq_refl _ $rhs) in
  Std.exact_no_check (Constr.Unsafe.make (Constr.Unsafe.Cast r Constr.Cast.vm g)).
Set Default Proof Mode "Ltac2".
Lemma LM2_cert16 : (match wstartx TM IMGW (vars_below (s_next (LM_EPI_P0 16))) 10 (LM_EPI_P0 16) P2RUN (NODES2 16) with
                    | Some l => forallb (fun X => fin_q (LM_Q 16) [0x976b0] (s_next (LM_EPI_P0 16)) (xs_st X)) l | None => false end) = true.
Proof. cert_refl_vm constr:(true). Qed.
Lemma LM2_cert0 : (match wstartx TM IMGW (vars_below (s_next (LM_EPI_P0 0))) 10 (LM_EPI_P0 0) P2RUN (NODES2 0) with
                   | Some l => forallb (fun X => fin_q (LM_Q 0) [0x976b0] (s_next (LM_EPI_P0 0)) (xs_st X)) l | None => false end) = true.
Proof. cert_refl_vm constr:(true). Qed.
Set Default Proof Mode "Classic".
End LmB.

Import OSSVerify.Proofs.fast_float.from_chars.lib.LM.LmThmFp.LmAD OSSVerify.Proofs.fast_float.from_chars.lib.LM.LmThmFp.LmA OSSVerify.Proofs.fast_float.from_chars.lib.LM.LmThmFp.LmB.
From OSSVerify.Proofs.fast_float.from_chars.lib.LM Require Import FxConstGen.
Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.

Lemma TM_eq : TM = mk_tbl ASEGS 0x96b2c 925.
Proof. vm_cast_no_check (eq_refl TM). Qed.
Lemma TM_nofp : tbl_nofp TM = true.
Proof. vm_cast_no_check (eq_refl true). Qed.
Lemma IMGW_eq : IMGW = mk_imgs_acc IMGR TEmpty.
Proof. vm_cast_no_check (eq_refl IMGW). Qed.
Lemma IMGW_ok : img_ok ASEGS IMGW.
Proof.
  rewrite IMGW_eq.
  apply mk_imgs_acc_ok; [unfold IMGR; repeat constructor; cbn; lia|]. intros p v Hp. rewrite tget_empty in Hp. discriminate.
Qed.
Lemma RET2_ok : Forall (is_ret ASEGS) [0x976b0].
Proof. repeat constructor. exists (Z_to_bv 32 0x00008067). (split; [|split]); vm_refl_bv. Qed.
Lemma sites1 : forall c, xsites (NODES c) = [] /\ xhandl (NODES c) = [] /\ xfsites (NODES c) = [] /\
  (forall P0' Q', In (P0', Q') (xksites (NODES c)) ->
     (P0', Q') = (SM5_P0, SM5_Q) \/ (P0', Q') = (MCA_P0, MCA_Q) \/ (P0', Q') = (MCB_P0, MCB_Q) \/ (P0', Q') = (MSX_P0, MSX_Q)).
Proof.
  intros c. split; [reflexivity|]. split; [reflexivity|]. split; [reflexivity|].
  intros P0' Q' H. cbn in H.
  repeat (destruct H as [H|H]; [first [left; exact (eq_sym H) | right; left; exact (eq_sym H) | right; right; left; exact (eq_sym H) | right; right; right; exact (eq_sym H)]|]).
  destruct H.
Qed.

Section LMFP.
Hypothesis H_SM5 : kfn_ok_fp ASEGS SM5_P0 SM5_Q.
Hypothesis H_MCA : kfn_ok_fp ASEGS MCA_P0 MCA_Q.
Hypothesis H_MCB : kfn_ok_fp ASEGS MCB_P0 MCB_Q.
Hypothesis H_MSX : kfn_ok_fp ASEGS MSX_P0 MSX_Q.
Hypothesis H_SF5 : kfn_ok_fp ASEGS SF5_P0 SF5_Q.

#[using="H_SM5 H_MCA H_MCB H_MSX"] Lemma c1_gen_fp : forall c ds,
  (match wstartx TM IMGW (vars_below (s_next (LM_P0 c))) 10 (LM_P0 c) P0RUN (xconst (NODES c) ds) with
   | Some l => forallb (fun X => fin_q (LM_TAIL_Q c) [0x973c8] (s_next (LM_P0 c)) (xs_st X)) l | None => false end) = true ->
  bases_wf (s_next (LM_P0 c)) (s_rgs (LM_P0 c)) = true -> bases_ins (vars_below (s_next (LM_P0 c))) (s_rgs (LM_P0 c)) = true ->
